import java.util.HashSet;
import java.util.Set;

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        Set<Character> jewelTypes = new HashSet<>();
        for (char c : jewels.toCharArray()) {
            jewelTypes.add(c);
        }

        int count = 0;
        for (char c : stones.toCharArray()) {
            if (jewelTypes.contains(c)) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        boolean[] isJewel = new boolean[128];
        for (int i = 0; i < jewels.length(); i++) {
            isJewel[jewels.charAt(i)] = true;
        }

        int count = 0;
        for (int i = 0; i < stones.length(); i++) {
            if (isJewel[stones.charAt(i)]) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        long mask = 0L;
        for (int i = 0; i < jewels.length(); i++) {
            int bit = index(jewels.charAt(i));
            mask |= 1L << bit;
        }

        int count = 0;
        for (int i = 0; i < stones.length(); i++) {
            int bit = index(stones.charAt(i));
            if ((mask & (1L << bit)) != 0) {
                count++;
            }
        }
        return count;
    }

    private int index(char c) {
        if (c >= 'a' && c <= 'z') {
            return c - 'a';
        }
        return 26 + c - 'A';
    }
}

import java.util.Arrays;

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        char[] jewelChars = jewels.toCharArray();
        Arrays.sort(jewelChars);

        int count = 0;
        for (int i = 0; i < stones.length(); i++) {
            if (Arrays.binarySearch(jewelChars, stones.charAt(i)) >= 0) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int numJewelsInStones(String jewels, String stones) {
        int count = 0;
        for (int i = 0; i < stones.length(); i++) {
            char stone = stones.charAt(i);
            for (int j = 0; j < jewels.length(); j++) {
                if (stone == jewels.charAt(j)) {
                    count++;
                    break;
                }
            }
        }
        return count;
    }
}
